package net.officefloor.hq.app.setting;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.sheet.DatedSettingLine;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

/** The sheet's policy versions, oldest first, each with the setting it recorded and how many claims it is the policy version of. */
@RestController
@Validated
@RequestMapping("/api/sheets/{sheetId}")
public class PolicyVersionController {

    /** A policy version: its number, from-date (null: none, the start), key, value (null: none) and claim count. */
    public record PolicyVersionView(int version, LocalDate from, String key, String value, long claims) {}

    private final SheetRepository sheets;
    private final ClaimRepository claims;

    public PolicyVersionController(SheetRepository sheets, ClaimRepository claims) {
        this.sheets = sheets;
        this.claims = claims;
    }

    @GetMapping("/policy-versions")
    @Transactional(readOnly = true)
    public List<PolicyVersionView> list(
            @PathVariable @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        Sheet sheet = sheets.findById(sheetId).orElse(null);
        if (sheet == null) return List.of();
        List<DatedSettingLine> log = sheet.getPolicyLog();
        long[] counts = new long[log.size() + 1];
        for (Claim claim : claims.findBySheetIdOrderByIdDesc(sheetId)) counts[sheet.policyVersionOn(claim.getDate())]++;
        List<PolicyVersionView> views = new ArrayList<>();
        for (int i = 0; i < log.size(); i++) {
            DatedSettingLine line = log.get(i);
            views.add(new PolicyVersionView(i + 1, line.getFrom(), line.getKey(), line.getValue(), counts[i + 1]));
        }
        return views;
    }
}
import { HttpClient } from '@angular/common/http';
import { Component, effect, inject, signal } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { Session } from '../../core/session';

/** A policy version: its number, from-date (null: none, the start), the setting it recorded and how many claims it is the policy version of. */
interface PolicyVersionView {
  version: number;
  from: string | null;
  key: string;
  value: string | null;
  claims: number;
}

// The sheet's policy versions, oldest first, as read from the store when shown: each line is
// <version> <from or start> <key>=<value> <count of claims whose policy version it is>.
@Component({
  selector: 'app-policy-versions',
  template: `
    <section aria-labelledby="policy-versions-heading">
      <h2 id="policy-versions-heading">Policy versions</h2>
      <button type="button" data-testid="policy-show" (click)="show()">Show policy versions</button>
      <ul aria-label="Policy versions">
        @for (v of versions(); track v.version) {
          <li data-testid="policy-line">{{ v.version }} {{ v.from ?? 'start' }} {{ v.key }}={{ v.value ?? '' }} {{ v.claims }}</li>
        }
      </ul>
    </section>
  `,
})
export class PolicyVersions {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);

  protected readonly versions = signal<PolicyVersionView[]>([]);

  constructor() {
    effect(() => {
      this.session.sheetId();
      this.session.loads();
      this.versions.set([]);
    });
  }

  protected async show(): Promise<void> {
    const sheet = this.session.sheetId();
    this.versions.set([]);
    if (!sheet) return;
    const views = await firstValueFrom(this.http.get<PolicyVersionView[]>(
      `/api/sheets/${encodeURIComponent(sheet)}/policy-versions`, { headers: { 'X-User': this.session.user() ?? '' } }));
    if (this.session.sheetId() === sheet) this.versions.set(views);
  }
}
/** A CSV field: wrapped in double quotes, any inside doubled, when it holds a comma, a quote or a line break. */
function csvField(value: string): string {
  return /[",\r\n]/.test(value) ? `"${value.replaceAll('"', '""')}"` : value;
}

/** Downloads the lines as a CSV file, each field quoted as needed and each line ended by a line feed. */
export function downloadCsv(lines: string[][], filename: string): void {
  const csv = lines.map((fields) => fields.map(csvField).join(',') + '\n').join('');
  const url = URL.createObjectURL(new Blob([csv], { type: 'text/csv' }));
  const link = document.createElement('a');
  link.href = url;
  link.download = filename;
  link.click();
  setTimeout(() => URL.revokeObjectURL(url));
}
